function sumTo(n) {
  let total = 0;
  let ops = 0;
  for (let i = 1; i <= n; i++) {
    total = total + i;
    ops = ops + 1;
  }
  return total + " in " + ops + " ops";
}

console.log(sumTo(5));
console.log(sumTo(10));
console.log(sumTo(100));

function sumToFast(n) {
  return (n * (n + 1)) / 2 + " in 3 ops";
}

