function halvingCost(n) {
  let steps = 0;
  while (n > 1) {
    n = Math.floor(n / 2);
    steps = steps + 1;
  }
  return steps;
}

function linearCost(arr) {
  let ops = 0;
  for (let i = 0; i < arr.length; i++) ops = ops + 1;
  return ops;
}

function quadraticCost(arr) {
  let ops = 0;
  for (let i = 0; i < arr.length; i++)
    for (let j = 0; j < arr.length; j++) ops = ops + 1;
  return ops;
}

const eight = [1, 2, 3, 4, 5, 6, 7, 8];
console.log(halvingCost(8), halvingCost(1024));
console.log(linearCost(eight), quadraticCost(eight));

