guided-practice.solution:
function countComparisons(arr, target) {
  let comparisons = 0;
  for (let i = 0; i < arr.length; i++) {
    comparisons = comparisons + 1;
    if (arr[i] === target) return comparisons;
  }
  return comparisons;
}

