  // seed the running maximum with arr[0], then compare every
  // later element against it, charging one comparison each time
  return comparisons;
}

exam.solution:
function countScans(arr) {
  let comparisons = 0;
  let biggest = arr[0];
  for (let i = 1; i < arr.length; i++) {
    comparisons = comparisons + 1;
    if (arr[i] > biggest) biggest = arr[i];
  }
  return comparisons;
}

